"""滑跃甲板圆弧几何：入口切线水平，出口切线角 = 资料给定滑跃角。

仅需出口切线角（°）；可选跳台唇口高度 h（m）确定圆弧半径 R = h / (1 − cos α)。
未给高度时用参考半径 SKI_JUMP_REF_RADIUS_M，弧长/水平投影/高度均由 R 与 α 导出。
"""
from __future__ import annotations

import math
from dataclasses import dataclass

# 仅给定滑跃角、无唇口高度时的参考圆弧半径，m（典型 STOBAR 量级）
SKI_JUMP_REF_RADIUS_M = 200.0


@dataclass(frozen=True)
class SkiJumpArc:
    angle_deg: float
    angle_rad: float
    radius_m: float
    arc_length_m: float
    horizontal_m: float
    lip_height_m: float

    @property
    def cos_exit(self) -> float:
        return math.cos(self.angle_rad)

    @property
    def sin_exit(self) -> float:
        return math.sin(self.angle_rad)


def compute_ski_jump_arc(angle_deg: float, lip_height_m: float | None = None,
                         radius_m: float | None = None) -> SkiJumpArc:
    """
    计算圆弧滑跃段几何。

    优先级：显式 radius_m > lip_height_m > 参考半径。
    """
    if angle_deg <= 0:
        raise ValueError('滑跃角必须为正')
    angle_rad = math.radians(angle_deg)
    if radius_m is not None and radius_m > 0:
        r = radius_m
        h = r * (1.0 - math.cos(angle_rad))
    elif lip_height_m is not None and lip_height_m > 0:
        h = lip_height_m
        r = h / (1.0 - math.cos(angle_rad))
    else:
        r = SKI_JUMP_REF_RADIUS_M
        h = r * (1.0 - math.cos(angle_rad))
    arc_length = r * angle_rad
    horizontal = r * math.sin(angle_rad)
    return SkiJumpArc(
        angle_deg=angle_deg,
        angle_rad=angle_rad,
        radius_m=r,
        arc_length_m=arc_length,
        horizontal_m=horizontal,
        lip_height_m=h,
    )


def deck_angle_rad_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """沿弧长 s 处甲板切线与水平面夹角（rad），0 → 出口角。"""
    if s_m <= 0:
        return 0.0
    return min(s_m / arc.radius_m, arc.angle_rad)


def deck_angle_deg_at_s(s_m: float, arc: SkiJumpArc) -> float:
    return math.degrees(deck_angle_rad_at_s(s_m, arc))


def deck_cos_sin_at_s(s_m: float, arc: SkiJumpArc) -> tuple[float, float]:
    phi = deck_angle_rad_at_s(s_m, arc)
    return math.cos(phi), math.sin(phi)


def horizontal_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """自滑跃入口起累计水平距离，m。"""
    phi = deck_angle_rad_at_s(s_m, arc)
    return arc.radius_m * math.sin(phi)


def deck_height_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """沿弧长 s 处甲板表面相对平甲板的高度，m。"""
    phi = deck_angle_rad_at_s(s_m, arc)
    return arc.radius_m * (1.0 - math.cos(phi))

py_sources.utils/search_utils.py:
"""Shared coarse/fine parameter search grids.

粗搜：模块级 ``range(start, stop + 1, step)``。
精搜：在粗搜最优值附近，对该变量 ± 粗搜步长；精搜步长默认为 1。
甲板/平直段长度精搜：仅向更短方向搜索 ``[best - coarse_step, best)``，因更长甲板不会更优。
"""


def grid_step(grid) -> int:
    """Return step size of a coarse ``range`` or sorted sequence."""
    if isinstance(grid, range):
        return grid.step or 1
    vals = list(grid)
    if len(vals) < 2:
        return 1
    return vals[1] - vals[0]


def fine_range_symmetric(best, coarse_step, fine_step=1, min_val=None, max_val=None):
    """Fine search grid: best ± coarse_step (inclusive endpoints)."""
    lo = int(best) - coarse_step
    hi = int(best) + coarse_step
    if min_val is not None:
        lo = max(lo, min_val)
    if max_val is not None:
        hi = min(hi, max_val)
    return range(lo, hi + 1, fine_step)


def fine_range_deck(best, coarse_step, fine_step=1, min_val=0):
    """Fine search for deck/runway length: only lengths shorter than *best*."""
    lo = max(int(best) - coarse_step, min_val)
    hi = int(best)
    if lo >= hi:
        return range(0)
    return range(lo, hi, fine_step)

py_sources.apps/saturation_strike_web.py:
"""饱和打击仿真 Web/JSON API（供 Pyodide / 小程序 / iOS 调用）。"""
from __future__ import annotations

import json
from typing import Any

from simulators.saturation_strike import (
    run_estimate_distance_from_params,
    run_estimate_pk_from_params,
    run_saturation_strike,
)
from utils.saturation_presets import build_saturation_presets_payload


def _opt_float(v: Any, default: float) -> float:
    """解析可选浮点，空值用默认。"""
    if v is None or v == '':
        return default
    return float(v)


def _opt_int(v: Any, default: int) -> int:
    """解析可选整数，空值用默认。"""
    if v is None or v == '':
        return default
    return int(round(float(v)))


def run_saturation(
    action: str = 'simulate',
    params: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """统一入口：simulate / estimate_distance / estimate_pk / presets。"""
    params = params or {}
    if action == 'presets':
        return {'success': True, 'presets': build_saturation_presets_payload()}
    if action == 'estimate_distance':
        try:
            result = run_estimate_distance_from_params(params)
            return {'success': True, **result}
        except Exception as exc:
            return {'success': False, 'error': str(exc)}
    if action == 'estimate_pk':
        try:
            result = run_estimate_pk_from_params(params)
            return {'success': True, **result}
        except Exception as exc:
            return {'success': False, 'error': str(exc)}
    if action != 'simulate':
        return {'success': False, 'error': f'未知 action: {action}'}

    try:
        fast = bool(params.get('fast', False))
        search_trials = _opt_int(params.get('search_trials'), 200 if fast else 900)
        final_trials = _opt_int(params.get('final_trials'), 800 if fast else 6000)
        result = run_saturation_strike(
            nm=_opt_int(params.get('nm'), 24),
            vm_ma=_opt_float(params.get('vm'), 2.6),
            discovery_km=_opt_float(params.get('D', params.get('discovery_km')), 120.0),
            ni=_opt_int(params.get('ni'), 16),
            vi_ma=_opt_float(params.get('vi'), 3.8),
            pk=_opt_float(params.get('pk'), 0.7),
            t_lock_s=_opt_float(params.get('tlock', params.get('t_lock_s')), 6.0),
            min_range_km=_opt_float(params.get('minr', params.get('min_range_km')), 3.0),
            search_trials=search_trials,
            final_trials=final_trials,
        )
        return result
    except Exception as exc:
        return {'success': False, 'error': str(exc)}


def run_saturation_json(payload: dict[str, Any] | str) -> dict[str, Any]:
    """解析 JSON/dict 载荷并运行饱和打击 API。"""
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except json.JSONDecodeError as exc:
            return {'success': False, 'error': f'JSON 解析失败: {exc}'}
    if not isinstance(payload, dict):
        return {'success': False, 'error': '载荷必须为对象'}
    action = str(payload.get('action', 'simulate'))
    params = payload.get('params')
    if params is None:
        # 允许扁平载荷（字段直接在根上）
        params = {k: v for k, v in payload.items() if k != 'action'}
    return run_saturation(action=action, params=params)
